mapper.select:
select id, code, sort, room_type_id, floor_id, is_deleted,
       create_by, create_time, update_by, update_time, remark
from room

    and code = #{code}
    and sort = #{sort}
    and room_type_id = #{roomTypeId}
    and floor_id = #{floorId}
    and is_deleted = #{isDeleted}

order by sort, id
